using System.ComponentModel;
using System.Net.Http.Json;
using ModelContextProtocol.Server;

namespace McpServer.Tools;

[McpServerToolType]
public sealed class ExternalApiTool
{
    [McpServerTool, Description("Fetches data from an external API for a given resource ID.")]
    public static async Task<string> FetchResource(
        IHttpClientFactory httpClientFactory,
        [Description("The resource ID to look up")] string resourceId,
        CancellationToken cancellationToken = default)
    {
        using var client = httpClientFactory.CreateClient("ExternalApi");

        var response = await client.GetAsync($"resources/{resourceId}", cancellationToken);
        response.EnsureSuccessStatusCode();

        var content = await response.Content.ReadAsStringAsync(cancellationToken);
        return content;
    }
}

using System.ComponentModel;
using ModelContextProtocol.Server;

namespace McpServer.Prompts;

[McpServerPromptType]
public sealed class SummarizationPrompt
{
    [McpServerPrompt, Description("Generates a prompt to summarize the given text.")]
    public static IEnumerable<ChatMessage> Summarize(
        [Description("The text content to summarize")] string text,
        [Description("Desired summary style: brief, detailed, or bullets")] string style = "brief")
    {
        var systemInstruction = style switch
        {
            "detailed" => "Provide a comprehensive summary that captures all key points.",
            "bullets" => "Summarize the text as a concise bullet-point list.",
            _ => "Provide a brief one-paragraph summary."
        };

        yield return new ChatMessage(ChatMessageRole.System, systemInstruction);
        yield return new ChatMessage(ChatMessageRole.User, $"Please summarize the following text:\n\n{text}");
    }
}

