using System.ComponentModel;
using ModelContextProtocol.Server;

namespace McpServer.Prompts;

[McpServerPromptType]
public sealed class SummarizationPrompt
{
    [McpServerPrompt, Description("Generates a prompt to summarize the given text.")]
    public static IEnumerable<ChatMessage> Summarize(
        [Description("The text content to summarize")] string text,
        [Description("Desired summary style: brief, detailed, or bullets")] string style = "brief")
    {
        var systemInstruction = style switch
        {
            "detailed" => "Provide a comprehensive summary that captures all key points.",
            "bullets" => "Summarize the text as a concise bullet-point list.",
            _ => "Provide a brief one-paragraph summary."
        };

        yield return new ChatMessage(ChatMessageRole.System, systemInstruction);
        yield return new ChatMessage(ChatMessageRole.User, $"Please summarize the following text:\n\n{text}");
    }
}

